  /// every mega-block footprint, so it carries the same migration contract as a placed block.</summary>
  public static readonly IReadOnlyList<Shipped> Exlib =
  [
    new("exlib", "structurefiller", "exlib:structurefiller", ["exlib:structurefiller"]),
  ];

  /// <summary>Every shipped blocktype across all three released mods.</summary>
  public static IEnumerable<Shipped> All => [.. Ppex, .. Smex, .. Exlib];

  /// <summary>Every concrete code that has ever been placed in a released world.</summary>
  public static IEnumerable<string> AllCodes =>
    System.Linq.Enumerable.SelectMany(All, s => s.Codes);
